import * as React from 'react'
import { Link } from 'gatsby'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import gridColours from "../data/grid-colours.json"

// ============================================
// Types & constants
// ============================================
interface Boid {
  x: number
  y: number
  vx: number
  vy: number
  colour: string
}

const BOID_COUNT_DESKTOP = 120
const BOID_COUNT_MOBILE = 60
const MAX_SPEED = 3
const SEPARATION_RADIUS = 25
const ALIGNMENT_RADIUS = 50
const COHESION_RADIUS = 80
const SEPARATION_WEIGHT = 1.5
const ALIGNMENT_WEIGHT = 1.0
const COHESION_WEIGHT = 1.0
const CURSOR_RADIUS = 150
const CURSOR_ATTRACT_WEIGHT = 0.8
const CURSOR_REPEL_WEIGHT = 2.0
const EDGE_MARGIN = 40
const EDGE_FORCE = 0.5
const TRAIL_ALPHA = 0.15
const BOID_LENGTH = 5
const BOID_WIDTH = 3

// ============================================
// Simulation helpers
// ============================================
function createBoid(w: number, h: number): Boid {
  const angle = Math.random() * Math.PI * 2
  const speed = 0.5 + Math.random() * 1.5
  return {
    x: Math.random() * w,
    y: Math.random() * h,
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    colour: gridColours[Math.floor(Math.random() * gridColours.length)],
  }
}

function clampSpeed(vx: number, vy: number): [number, number] {
  const speed = Math.sqrt(vx * vx + vy * vy)
  if (speed > MAX_SPEED) {
    const scale = MAX_SPEED / speed
    return [vx * scale, vy * scale]
  }
  if (speed < 0.3) {
    const scale = 0.3 / (speed || 0.01)
    return [vx * scale, vy * scale]
  }
  return [vx, vy]
}

function updateBoids(
  boids: Boid[],
  w: number,
  h: number,
  cursorX: number,
  cursorY: number,
  cursorActive: boolean,
  repelling: boolean,
) {
  const len = boids.length

  for (let i = 0; i < len; i++) {
    const b = boids[i]
    let sepX = 0, sepY = 0
    let aliVx = 0, aliVy = 0, aliCount = 0
    let cohX = 0, cohY = 0, cohCount = 0

    for (let j = 0; j < len; j++) {
      if (i === j) continue
      const o = boids[j]
      const dx = o.x - b.x
      const dy = o.y - b.y
      const dist = Math.sqrt(dx * dx + dy * dy)

      if (dist < SEPARATION_RADIUS && dist > 0) {
        sepX -= dx / dist
        sepY -= dy / dist
      }
      if (dist < ALIGNMENT_RADIUS) {
        aliVx += o.vx
        aliVy += o.vy
        aliCount++
      }
      if (dist < COHESION_RADIUS) {
        cohX += o.x
        cohY += o.y
        cohCount++
      }
    }

    let steerX = sepX * SEPARATION_WEIGHT
    let steerY = sepY * SEPARATION_WEIGHT

    if (aliCount > 0) {
      steerX += (aliVx / aliCount - b.vx) * ALIGNMENT_WEIGHT * 0.1
      steerY += (aliVy / aliCount - b.vy) * ALIGNMENT_WEIGHT * 0.1
    }

    if (cohCount > 0) {
      const avgX = cohX / cohCount
      const avgY = cohY / cohCount
      steerX += (avgX - b.x) * COHESION_WEIGHT * 0.005
      steerY += (avgY - b.y) * COHESION_WEIGHT * 0.005
    }

    // Cursor influence
    if (cursorActive) {
      const cdx = cursorX - b.x
      const cdy = cursorY - b.y
      const cdist = Math.sqrt(cdx * cdx + cdy * cdy)
      if (cdist < CURSOR_RADIUS && cdist > 0) {
        const strength = (1 - cdist / CURSOR_RADIUS)
        if (repelling) {
          steerX -= (cdx / cdist) * strength * CURSOR_REPEL_WEIGHT
          steerY -= (cdy / cdist) * strength * CURSOR_REPEL_WEIGHT
        } else {
          steerX += (cdx / cdist) * strength * CURSOR_ATTRACT_WEIGHT
          steerY += (cdy / cdist) * strength * CURSOR_ATTRACT_WEIGHT
        }
      }
    }

    // Edge avoidance
    if (b.x < EDGE_MARGIN) steerX += EDGE_FORCE * (1 - b.x / EDGE_MARGIN)
    if (b.x > w - EDGE_MARGIN) steerX -= EDGE_FORCE * (1 - (w - b.x) / EDGE_MARGIN)
    if (b.y < EDGE_MARGIN) steerY += EDGE_FORCE * (1 - b.y / EDGE_MARGIN)
    if (b.y > h - EDGE_MARGIN) steerY -= EDGE_FORCE * (1 - (h - b.y) / EDGE_MARGIN)

    b.vx += steerX
    b.vy += steerY
    ;[b.vx, b.vy] = clampSpeed(b.vx, b.vy)

    b.x += b.vx
    b.y += b.vy

    // Hard clamp within bounds
    if (b.x < 0) { b.x = 0; b.vx = Math.abs(b.vx) }
    if (b.x > w) { b.x = w; b.vx = -Math.abs(b.vx) }
    if (b.y < 0) { b.y = 0; b.vy = Math.abs(b.vy) }
    if (b.y > h) { b.y = h; b.vy = -Math.abs(b.vy) }
  }
}

function renderBoids(
  ctx: CanvasRenderingContext2D,
  boids: Boid[],
  w: number,
  h: number,
  dpr: number,
) {
  // Trail effect: semi-transparent fill over previous frame
  ctx.fillStyle = `rgba(10, 25, 47, ${TRAIL_ALPHA})`
  ctx.fillRect(0, 0, w * dpr, h * dpr)

  ctx.save()
  ctx.scale(dpr, dpr)

  for (let i = 0; i < boids.length; i++) {
    const b = boids[i]
    const angle = Math.atan2(b.vy, b.vx)

    ctx.save()
    ctx.translate(b.x, b.y)
    ctx.rotate(angle)
    ctx.beginPath()
    ctx.ellipse(0, 0, BOID_LENGTH, BOID_WIDTH, 0, 0, Math.PI * 2)
    ctx.fillStyle = b.colour
    ctx.globalAlpha = 0.85
    ctx.fill()
    ctx.restore()
  }

  ctx.restore()
}

// ============================================
// Page component
// ============================================
const FlockPage: React.FC = () => {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const wrapperRef = React.useRef<HTMLDivElement>(null)
  const boidsRef = React.useRef<Boid[]>([])
  const cursorRef = React.useRef({ x: 0, y: 0, active: false, repelling: false })
  const sizeRef = React.useRef({ w: 0, h: 0 })
  const rafRef = React.useRef<number>(0)

  React.useEffect(() => {
    const canvas = canvasRef.current
    const wrapper = wrapperRef.current
    if (!canvas || !wrapper) return

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const dpr = window.devicePixelRatio || 1
    const isMobile = window.innerWidth < 600
    const boidCount = isMobile ? BOID_COUNT_MOBILE : BOID_COUNT_DESKTOP

    // Size canvas to wrapper
    const resize = () => {
      const rect = wrapper.getBoundingClientRect()
      const w = rect.width
      const h = rect.height
      sizeRef.current = { w, h }
      canvas.width = w * dpr
      canvas.height = h * dpr
      canvas.style.width = `${w}px`
      canvas.style.height = `${h}px`

      // Clear to background colour on resize
      ctx.fillStyle = '#0A192F'
      ctx.fillRect(0, 0, canvas.width, canvas.height)
    }

    resize()

    // Initialize boids
    const { w, h } = sizeRef.current
    boidsRef.current = Array.from({ length: boidCount }, () => createBoid(w, h))

    // ResizeObserver
    const ro = new ResizeObserver(resize)
    ro.observe(wrapper)

    // Animation loop
    const tick = () => {
      const { w: cw, h: ch } = sizeRef.current
      if (cw > 0 && ch > 0) {
        const { x, y, active, repelling } = cursorRef.current
        updateBoids(boidsRef.current, cw, ch, x, y, active, repelling)
        renderBoids(ctx, boidsRef.current, cw, ch, dpr)
      }
      rafRef.current = requestAnimationFrame(tick)
    }
    rafRef.current = requestAnimationFrame(tick)

    // Mouse handlers
    const onMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect()
      cursorRef.current.x = e.clientX - rect.left
      cursorRef.current.y = e.clientY - rect.top
      cursorRef.current.active = true
    }
    const onMouseDown = () => { cursorRef.current.repelling = true }
    const onMouseUp = () => { cursorRef.current.repelling = false }
    const onMouseLeave = () => { cursorRef.current.active = false }

    // Touch handlers
    const onTouchStart = (e: TouchEvent) => {
      e.preventDefault()
      const touch = e.touches[0]
      const rect = canvas.getBoundingClientRect()
      cursorRef.current.x = touch.clientX - rect.left
      cursorRef.current.y = touch.clientY - rect.top
      cursorRef.current.active = true
    }
    const onTouchMove = (e: TouchEvent) => {
      e.preventDefault()
      const touch = e.touches[0]
      const rect = canvas.getBoundingClientRect()
      cursorRef.current.x = touch.clientX - rect.left
      cursorRef.current.y = touch.clientY - rect.top
    }
    const onTouchEnd = () => {
      cursorRef.current.active = false
      cursorRef.current.repelling = false
    }

    canvas.addEventListener('mousemove', onMouseMove)
    canvas.addEventListener('mousedown', onMouseDown)
    canvas.addEventListener('mouseup', onMouseUp)
    canvas.addEventListener('mouseleave', onMouseLeave)
    canvas.addEventListener('touchstart', onTouchStart, { passive: false })
    canvas.addEventListener('touchmove', onTouchMove, { passive: false })
    canvas.addEventListener('touchend', onTouchEnd)

    return () => {
      cancelAnimationFrame(rafRef.current)
      ro.disconnect()
      canvas.removeEventListener('mousemove', onMouseMove)
      canvas.removeEventListener('mousedown', onMouseDown)
      canvas.removeEventListener('mouseup', onMouseUp)
      canvas.removeEventListener('mouseleave', onMouseLeave)
      canvas.removeEventListener('touchstart', onTouchStart)
      canvas.removeEventListener('touchmove', onTouchMove)
      canvas.removeEventListener('touchend', onTouchEnd)
    }
  }, [])

  return (
    <div className="container">
      <Header />
      <div className="flock__hero">
        <Link to="/code" className="back-link">&larr; Code</Link>
        <h1>Flock</h1>
        <p>Move your cursor to attract &mdash; click to scatter</p>
        <AccentDots />
      </div>
      <div className="flock__wrapper" ref={wrapperRef}>
        <canvas ref={canvasRef} className="flock__canvas" />
      </div>
      <Footer />
    </div>
  )
}

export default FlockPage
